import{_ as s,o as e,c as n,ah as o}from"./chunks/framework.DD-aSpuQ.js";const r="/projects/JetAuto/en/jetauto-orin-nano/assets/image2.C6-fOXe5.png",h="/projects/JetAuto/en/jetauto-orin-nano/assets/image3.DwMp1iqc.jpeg",l="/projects/JetAuto/en/jetauto-orin-nano/assets/image4.BWBzoUnY.jpeg",p="/projects/JetAuto/en/jetauto-orin-nano/assets/image5._1qH-YNJ.png",d="/projects/JetAuto/en/jetauto-orin-nano/assets/image6.DMY9IstT.png",c="/projects/JetAuto/en/jetauto-orin-nano/assets/image7.D3i6horO.png",g="/projects/JetAuto/en/jetauto-orin-nano/assets/image8.itO2cHPP.png",m="/projects/JetAuto/en/jetauto-orin-nano/assets/image9.sF06qlM_.png",u="/projects/JetAuto/en/jetauto-orin-nano/assets/image10.NDOxVOho.png",k="data:image/png;base64,",A="/projects/JetAuto/en/jetauto-orin-nano/assets/image12.BfBZ2SK1.png",b="/projects/JetAuto/en/jetauto-orin-nano/assets/image13.Z6rFE688.png",F="/projects/JetAuto/en/jetauto-orin-nano/assets/image14.vhdhRJgC.png",v="/projects/JetAuto/en/jetauto-orin-nano/assets/image15.BY5LYkqT.png",i="data:image/png;base64,",a="/projects/JetAuto/en/jetauto-orin-nano/assets/image19.CGQ8MIpb.png",j=JSON.parse('{"title":"3. ROS2-Lidar Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.lidar.md","filePath":"docs/3.lidar.md"}'),y={name:"docs/3.lidar.md"};function C(f,t,E,w,B,z){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="_3-ros2-lidar-course" tabindex="-1">3. ROS2-Lidar Course <a class="header-anchor" href="#_3-ros2-lidar-course" aria-label="Permalink to &quot;3. ROS2-Lidar Course&quot;">​</a></h1><h2 id="_3-1-lidar-introduction" tabindex="-1">3.1 Lidar Introduction <a class="header-anchor" href="#_3-1-lidar-introduction" aria-label="Permalink to &quot;3.1 Lidar Introduction&quot;">​</a></h2><h3 id="_3-1-1-preface" tabindex="-1">3.1.1 Preface <a class="header-anchor" href="#_3-1-1-preface" aria-label="Permalink to &quot;3.1.1 Preface&quot;">​</a></h3><p>Lidar, a high-precision and high-speed remote sensing technology, is pivotal in numerous domains, including map creation, autonomous driving, environmental perception, and robot navigation. This document provides an overview of Lidar&#39;s principles, components, working mechanisms, application areas, advantages, and development trends.</p><p>In autonomous driving and intelligent transportation, Lidar assumes a critical role by offering real-time perception of obstacles, pedestrians, and vehicles on the road, providing precise distance and location information. In robot navigation and environmental perception, Lidar contributes by furnishing accurate maps and information about the surrounding environment. Furthermore, Lidar finds extensive applications in areas such as 3D modeling, map creation, safety monitoring, and remote sensing mapping.</p><img loading="lazy" height="330" width="611" class="common_img" src="'+r+'"><h3 id="_3-1-2-lidar-composition-and-classification" tabindex="-1">3.1.2 Lidar Composition and Classification <a class="header-anchor" href="#_3-1-2-lidar-composition-and-classification" aria-label="Permalink to &quot;3.1.2 Lidar Composition and Classification&quot;">​</a></h3><p>Lidar is composed of essential components such as a laser emitter, receiver, photodetector, scanning mechanism, and angle resolver. The laser emitter produces laser beams, while the receiver and photodetector capture reflected light signals. The scanning mechanism is responsible for surveying the surrounding environment, and the angle resolver assists in determining the position of target objects.</p><p>Lidar can be categorized into various types based on the scanning method:</p><p><strong>Rotating Lidar</strong>: Achieves omnidirectional scanning horizontally by rotating the emitter or scanning mechanism. Known for high scanning speed and measurement accuracy, it is widely applied in areas such as autonomous driving, 3D environmental modeling, and map creation.</p><p><strong>Solid-State Lidar</strong>: Utilizes solid-state laser emitters, eliminating the need for rotating components. Compact, lightweight, and energy-efficient, solid-state lidar is suitable for applications like mobile devices, drones, and robots.</p><p><strong>Mechanical Lidar</strong>: Employs mechanical components like rotating mirrors or prisms for laser beam scanning. Although offering longer measurement distances and higher accuracy, mechanical lidar tends to have slower scanning speeds. It is commonly used in terrain measurement, building scanning, and navigation.</p><p><strong>Phase-Modulated Lidar</strong>: Measures the distance between target objects and the lidar by altering the phase of the laser beam. Known for high measurement accuracy and a large measurement range, phase-modulated lidar is extensively used in map creation, surveying, and industrial applications.</p><p><strong>Flash Lidar</strong>: Utilizes brief, high-power laser pulses to illuminate the entire scene simultaneously. It captures reflected light signals through an array of receivers, making it suitable for high-speed and high-resolution applications, including rapid scene capture and motion tracking.</p><h3 id="_3-1-3-switch-lidar-version" tabindex="-1">3.1.3 Switch Lidar Version <a class="header-anchor" href="#_3-1-3-switch-lidar-version" aria-label="Permalink to &quot;3.1.3 Switch Lidar Version&quot;">​</a></h3><p>Multiple LiDAR sensors, including models like the A1 and G4, are compatible with the robot. To check the current LiDAR model or switch to a different one, follow these steps (applicable to all JetAuto series robots):</p><p>(1) Confirm the robot&#39;s Lidar version. As shown below, the left image is the A1 Lidar, and the right image is the G4 Lidar.</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="602" width="606" src="'+h+'" style="width:420px;"><img loading="lazy" height="586" width="606" src="'+l+'" style="width:420px;"></p><p>(2) Start the robot, and connect it to NoMachine according to the instructions provided in <a href="./1.quick_start_guide.html#development-environment-setup-and-configuration"><strong>1. Quick Start Guide(JetAuto User Manual) -&gt;1.6 Development Environment Setup and Configuration</strong></a>.</p><img loading="lazy" height="678" width="1265" class="common_img" src="'+p+'"><p>(3) After successful connection, double-click <img loading="lazy" height="67" width="48" src="'+d+'">.</p><img loading="lazy" height="357" width="690" class="common_img" src="'+c+'"><p>(4) Click-on Lidar TAB, and select &quot;<strong>G4</strong>&quot;, then click-on &quot;<strong>Save</strong>&quot; and &quot;<strong>Apply</strong>&quot; in sequence.</p><img loading="lazy" height="351" width="692" class="common_img" src="'+g+'"><p>(5) A pop-up window like the one below will appear. The robot&#39;s auto-start service will restart, and the LiDAR model will be configured based on the selected option.</p><img loading="lazy" height="356" width="696" class="common_img" src="'+m+'"><p>(6) After the system completes a restart, click-on &quot;<strong>Quit</strong>&quot; icon.</p><img loading="lazy" height="354" width="687" class="common_img" src="'+u+'"><p>(7) Finally, click-on <img loading="lazy" height="44" width="53" src="'+k+'"> to confirm the Lidar version.</p><img loading="lazy" height="305" width="687" class="common_img" src="'+A+'"><h2 id="_3-2-lidar-working-and-ranging-principle" tabindex="-1">3.2 Lidar Working and Ranging Principle <a class="header-anchor" href="#_3-2-lidar-working-and-ranging-principle" aria-label="Permalink to &quot;3.2 Lidar Working and Ranging Principle&quot;">​</a></h2><h3 id="_3-2-1-lidar-ranging" tabindex="-1">3.2.1 Lidar Ranging <a class="header-anchor" href="#_3-2-1-lidar-ranging" aria-label="Permalink to &quot;3.2.1 Lidar Ranging&quot;">​</a></h3><p>Two common methods are employed by Lidar to determine the distance to a target: triangulation and Time of Flight (TOF).</p><p>In the case of TOF, as depicted in the diagram, the Lidar initially projects light onto the object. The object reflects the light directly back to the Lidar, which calculates the time it takes for the light to return. The distance between the object and the Lidar is then obtained by multiplying this time by the speed of light.</p><img loading="lazy" height="311" width="820" class="common_img" src="'+b+'"><p>In triangulation, as illustrated in the diagram, the Lidar undergoes adjustments during manufacturing to ensure that the light does not directly strike the object. Instead, it is projected at a specific angle, a pre-set value that remains constant during operation. The distance from the object to the Lidar can be calculated by incorporating this angle into trigonometric functions.</p><img loading="lazy" height="313" width="809" class="common_img" src="'+F+'"><h3 id="_3-2-2-lidar-working-result" tabindex="-1">3.2.2 Lidar Working Result <a class="header-anchor" href="#_3-2-2-lidar-working-result" aria-label="Permalink to &quot;3.2.2 Lidar Working Result&quot;">​</a></h3><p>Its working result is as follows. Lidar will emit light and shine it on the object surface. When receiving the light reflected by the object, Lidar will mark the contour of the object at the position where the light is reflected.</p><img loading="lazy" height="556" width="770" class="common_img" src="'+v+'"><h2 id="_3-3-lidar-obstacle-avoidance" tabindex="-1">3.3 Lidar Obstacle Avoidance <a class="header-anchor" href="#_3-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;3.3 Lidar Obstacle Avoidance&quot;">​</a></h2><p>The robot senses the distance between itself and an object directly in front of it. Depending on the configured distance, the robot will either turn left or right to avoid obstacles. If no obstacles are detected, it will proceed to move forward.</p><p>This game can be activated in two ways: either through a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.quick_start_guide.html#app-control"><strong>1.Quick Start Guide(JetAuto User Manual)-&gt;1.5 APP Control</strong></a></p><p>(1) Start the robot, and access the robot system desktop using NoMachine.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+i+'"> to initiate the command-line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><p>(4) Next, type the command and press Enter to activate the robot&#39;s auto-start program.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>(5) Open a new terminal, and execute the command, then press Enter to start the Lidar game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><img loading="lazy" height="99" width="739" class="common_img" src="'+a+'"><p>(6) Enter the command and hit Enter to launch Lidar obstacle avoidance game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 1}&quot;</span></span></code></pre></div><p>(7) To stop the current function, enter the command in the terminal and press Enter to execute it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To exit the game mode, simply press &quot;<strong>Ctrl+C</strong>&quot; in the terminal interface at step (4) or (5).</p><h3 id="_3-3-1-lidar-following" tabindex="-1">3.3.1 Lidar Following <a class="header-anchor" href="#_3-3-1-lidar-following" aria-label="Permalink to &quot;3.3.1 Lidar Following&quot;">​</a></h3><p>The robot will detect the distance between itself and objects directly in front of it. If the distance is too close to an obstacle, it will perform a turning maneuver to avoid it.</p><p>This game can be activated in two ways: either through a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.quick_start_guide.html#app-control"><strong>1.Quick Start Guide(JetAuto User Manual)-&gt;1.5 APP Control</strong></a></p><p>(1) Start the robot, and access the robot system desktop using NoMachine.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+i+'"> to initiate the command line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><p>(4) Run the command to enable the local services for app-related game and chassis control services.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>(5) Open a new command-line terminal, and execute the command, then press Enter to start the Lidar game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><img loading="lazy" height="99" width="739" class="common_img" src="'+a+'"><p>(6) Enter the command and hit Enter to launch Lidar following game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 2}&quot;</span></span></code></pre></div><p>(7) To stop the current function, just type the command in the terminal and press Enter to execute it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To stop the process, simply press &#39;<strong>Ctrl+C</strong>&#39; in the terminal window from steps 4) or 5).</p><h3 id="_3-3-2-lidar-guarding" tabindex="-1">3.3.2 Lidar Guarding <a class="header-anchor" href="#_3-3-2-lidar-guarding" aria-label="Permalink to &quot;3.3.2 Lidar Guarding&quot;">​</a></h3><p>The robot assesses the distance between itself and an object directly in front. If an object is detected within the configured distance, it will initiate a turn to ensure that the vehicle consistently faces the object.</p><p>This game can be activated through two methods: either via a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.quick_start_guide.html#app-control">1.Quick Start Guide(JetAuto User Manual)-&gt;1.5 APP Control</a></p><p>(1) Start the robot, and access the robot system desktop using NoMachine.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+i+'"> to open the command line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><p>(4) Run the command to enable the local services for app-related game and chassis control services.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lidar_node.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>(5) Open a new ROS2 terminal, and execute the command, then press Enter to start the Lidar game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> std_srvs/srv/Trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span></span></code></pre></div><img loading="lazy" height="99" width="739" class="common_img" src="'+a+'"><p>(6) Enter the command and hit Enter to launch Lidar guarding game.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 3}&quot;</span></span></code></pre></div><p>(7) To stop the current function, type the command in the terminal and press Enter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interfaces/srv/SetInt64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To exit the game mode, simply press <strong>&quot;Ctrl+C&quot;</strong> in the terminal interface at step (4) or (5).</p>',94)])])}const I=s(y,[["render",C]]);export{j as __pageData,I as default};
